style.css:
/* CSS para Stylish - Arial em todos os sites */
* {
    font-family: Arial, sans-serif !important;
}

/* Garante que elementos com fontes específicas também sejam substituídos */
body, div, p, span, a, h1, h2, h3, h4, h5, h6, li, td, input, textarea, button, select {
    font-family: Arial, sans-serif !important;
}

/* Corrige possíveis problemas em inputs e textareas */
input, textarea, button, select {
    font-family: Arial, sans-serif !important;
}
